--新春祈愿
function GachaponConfirm:FillNewYearPray()
    CfUtils.SetActive(self.GoodIconNode, false)
    CfUtils.SetActive(self.SubText2, true)
    CfUtils.SetActive(self.HeadIconNode, true)

    CfUtils.FillText(self.TipsTitle, localize("是否祈愿该武装"))
    CfUtils.FillText(self.SubText2, localize("选择后在获得该武装前不可更改"))

    local scr = CfUtils.GetLuaScr(self.HeadIconNode.transform:Find("CommonSmallHeadNode"), "Game.Behaviours.CardHeadNode")
    if scr then
        scr:FreshNodeByCardVo(self._leftParam.roleId)
        scr:SetCallBack(function()
            local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(self._leftParam.roleId)
            GameUtils.ShowCommonTipsBoard(self.HeadIconNode.transform:Find("CommonSmallHeadNode").gameObject, vo.name, vo.desc, vo.quality, vo.id)
        end)
    end
end

