function GachaponConfirm:FillAllStaticText()
    self.BtnCancel.transform:Find("Text").gameObject:GetComponent(typeof(TextComp)).text = localize("取消")

    if checkNumber(self._type) == GachaponConstants.ConfirmType.ChooseCard then
        self.BtnConfirm.transform:Find("Text").gameObject:GetComponent(typeof(TextComp)).text = localize("祈愿")
    else
        self.BtnConfirm.transform:Find("Text").gameObject:GetComponent(typeof(TextComp)).text = localize("确认")
    end
end

function GachaponConfirm:InitLayout()
    KTool.SetActive(self.itemCell.gameObject, false)
    KTool.SetActive(self.countCell.gameObject, false)

    local itemIns = GameObject.Instantiate(self.itemCell.gameObject, self.leftPos)
    itemIns.transform.localPosition = CS.UnityEngine.Vector3.zero
    --itemIns.transform.localScale = Vector3.New(1, 1, 1)
    local name1 = self:UpdateItemCell(itemIns.transform, self._leftParam.goodsId, self._leftParam.num)
    KTool.SetActive(itemIns.gameObject, true)

    if self._type == GachaponConstants.ConfirmType.IconToIcon  or self._type == GachaponConstants.ConfirmType.CARD_SKIN then


        itemIns = GameObject.Instantiate(self.itemCell.gameObject, self.rightPos)
        itemIns.transform.localPosition = CS.UnityEngine.Vector3.zero
        --itemIns.transform.localScale = Vector3.New(1, 1, 1)
        local name2 = self:UpdateItemCell(itemIns.transform, self._rightParam.goodsId, self._rightParam.num)
        KTool.SetActive(itemIns.gameObject, true)

        if GachaponUtils.IsEquipType(self._poolType) then
            self.TipsTitle.text = localize("_name1不足", {
                 _name1_ = name2, 
            })
        else
            self.TipsTitle.text = localize("是否消耗_cnt1__name1_兑换_cnt2__name2_并进行召唤？", {
                _cnt1_ = self._leftParam.num, _name1_ = name1, _cnt2_ = self._rightParam.num, _name2_ = name2
            })
        end
        

    elseif self._type == GachaponConstants.ConfirmType.IconToCount then
        itemIns = GameObject.Instantiate(self.countCell.gameObject, self.rightPos)
        itemIns.transform.localPosition = CS.UnityEngine.Vector3.zero
        --itemIns.transform.localScale = Vector3.New(1, 1, 1)
        self:UpdateCountCell(itemIns.transform, self._rightParam.num)
        KTool.SetActive(itemIns.gameObject, true)

        if GachaponUtils.IsEquipType(self._poolType) then
            self.TipsTitle.text = localize("是否消耗_cnt1__name1_兑换_cnt2_个卡包？", {
                _cnt1_ = self._leftParam.num, _name1_ = name1, _cnt2_ = self._rightParam.num
            })
        else
            self.TipsTitle.text = localize("是否消耗_cnt1__name1_召唤_cnt2_次情绪武装？", {
                _cnt1_ = self._leftParam.num, _name1_ = name1, _cnt2_ = self._rightParam.num
            })
        end

    end

    local id 
    local idCnt 
    local disName 

    if not GachaponUtils.IsEquipType(self._poolType) then
        id = self._leftParam.goodsId
        idCnt = self._leftParam.num
        local setting = GoodsConfMgr:GetInstance():GetGoodsVoById(id) or {}
        disName = setting.name
    else
        if self._type == GachaponConstants.ConfirmType.IconToIcon then
            id = self._rightParam.goodsId
            idCnt = self._rightParam.num
            disName = name1
        else
            id = self._leftParam.goodsId
            idCnt = self._leftParam.num
            local setting = GoodsConfMgr:GetInstance():GetGoodsVoById(id) or {}
            disName = setting.name
        end
        
    end

    local cnt = GoodsUtils.GetThingNo(id)

    if cnt < idCnt then
        KTool.SetActive(self.failTest.gameObject, true)
        KTool.SetActive(self.ButtonNode.gameObject, false)
        self.btmTips.text = localize("_name_不足请前往兑换",{_name_ = disName})
        CfUtils.FillText(self.btnStore.transform:Find("Text").gameObject, localize("前往兑换"))
        SetButtonAction(self.btnStore, function()
            if self._type == GachaponConstants.ConfirmType.CARD_SKIN then
                local t = {}
                local dialogs = UIModule.CurrentScreen.dialogs
                for _, dialog in pairs(dialogs) do
                    if checkNumber(dialog.Argument.id) ~= self.controller.Argument.id  then
                        table.insert(t, dialog.Argument)
                    end
                end
                UIModule.CloseDialog(self.controller)
                UIModule.OpenDialog({ id = Constants.UITypeIds.OverseaStore},t)
                -- CfUtils.DialogOpen(Constants.UITypeIds.OverseaStore, nil, t)
            else 
                local StoreUtils = import('Game.UI.Store.StoreUtils')
                local StoreConstants = import('Game.UI.Store.StoreConstants')
                local ids = {
                    {id = Constants.UITypeIds.GachaponEntry}, 
                    {id = Constants.UITypeIds.GachaponResultViewNew},
                    {id = Constants.UITypeIds.GachaponResultViewSpecial},
                }
    
                cs_coroutine.start(function()
                    if GachaponUtils.IsEquipType(self._poolType) then 
                        coroutine.yield(StoreUtils.OpenStore(StoreConstants.OpenIds.Supply, ids))
                    else
                        StoreUtils.OpenDiamondExchangeDialog()
                    end
                    self.controller:Close()
                end)    
            end
           
        end)

    else
        KTool.SetActive(self.failTest.gameObject, false)
    end
end

function GachaponConfirm:UpdateItemCell(trans, id, num)
    local setting = GoodsConfMgr:GetInstance():GetGoodsVoById(id) or {}
    --local img = trans:Find("icon").gameObject:GetComponent(typeof(ImageComp))
    --local path = setting.photoPath
    --GachaponUtils.LoadSpriteAsync(img, path)
    --img = trans:Find("rare").gameObject:GetComponent(typeof(ImageComp))
    --path = string.format(GachaponConstants.ResultPopRareBg, setting.quality)
    --GachaponUtils.LoadSpriteAsync(img, path)
    --trans:Find("num").gameObject:GetComponent(typeof(TextComp)).text = string.format(GachaponConstants.GachaponConfirmTips.ItemNumStr, num)
    local env = GetLuaBehaviour(trans.gameObject, Constants.UILuaTablePath.GoodNodeMB)
    if not isNull(env) then
        if isNull(env.Env) then
            env:Init()
        end
        
        env.Env:Reload({
            goodsId = id,
            text = num,
            isShowNo = true
        })
    end
    return setting.name
end

function GachaponConfirm:UpdateCountCell(trans, num)
    trans:Find("num").gameObject:GetComponent(typeof(TextMeshProUGUI)).text = tostring(num)
end

return GachaponConfirm